import React, { useState } from "react";
import "./adminPortfolio.css";

const AdminPortfolio = () => {
  const [isMenuVisible, setIsMenuVisible] = useState(false);

  const toggleMenu = () => {
    setIsMenuVisible(!isMenuVisible);
  };

  const handleMenuClick = (option) => {
    // Logic for handling menu options
    console.log(`${option} clicked`);
    setIsMenuVisible(false);
  };

  const handleViewClick = (id) => {
    console.log(`View button clicked for project with ID: ${id}`);
    // Add logic to view project details
  };

  return (
    <div>
      {/* Header */}
      <header>
        <div className="hamburger" onClick={toggleMenu}>
          &#9776; {/* Hamburger icon */}
        </div>
        <h1>Admin Portfolio</h1>
        <button className="sign-out-btn" onClick={() => handleMenuClick("Sign Out")}>
          Sign Out
        </button>
      </header>

      {/* Sidebar Menu */}
      <div className={`sidebar ${isMenuVisible ? "visible" : ""}`}>
        <ul>
          <li onClick={() => handleMenuClick("List of Users")}>List of Users</li>
          <li onClick={() => handleMenuClick("List of Builders")}>List of Builders</li>
        </ul>
      </div>

      {/* Main Content */}
      <main>
        <div className="table-container">
          <h2>Project Table</h2>
          <div className="table-wrapper">
            <table>
              <thead>
                <tr>
                  <th>PID</th>
                  <th>Status</th>
                  <th>Username</th>
                  <th>Builder Name</th>
                  <th>Date</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td>1</td>
                  <td>Active</td>
                  <td>John Doe</td>
                  <td>Builder Inc.</td>
                  <td>2024-08-08</td>
                  <td>
                    <button className="view-btn" onClick={() => handleViewClick(1)}>View</button>
                  </td>
                </tr>
                {/* Additional rows can be added here */}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPortfolio;
